import re
import subprocess
import os
from flask import Flask, request, jsonify

app = Flask(__name__)

@app.route('/monitor/commands', methods=['POST'])
def monitor_commands():
    data = request.get_json(silent=True)
    if not data:
        return jsonify({"code": 400, "message": "Invalid request body"}), 400

    if 'command_regex' not in data:
        return jsonify({"code": 400, "message": "'command_regex' is required"}), 400

    command_regex = data['command_regex']
    filter_flags = data.get('filter_flags', 'aux')

    try:
        # Build ps command safely
        ps_command = ['ps', filter_flags, '-o', 'pid=,comm=']
        result = subprocess.run(ps_command, capture_output=True, text=True, timeout=10)
    except Exception as e:
        return jsonify({"code": 500, "message": f"Failed to execute ps: {str(e)}"}), 500

    if result.returncode != 0:
        return jsonify({"code": 500, "message": f"ps command failed: {result.stderr}"}), 500

    lines = result.stdout.strip().split('\n')
    matches = []

    for line in lines:
        line = line.strip()
        if not line:
            continue
        parts = line.split(maxsplit=1)
        if len(parts) < 2:
            continue
        pid_str, comm = parts[0], parts[1]
        try:
            pid = int(pid_str)
        except ValueError:
            continue

        if re.search(command_regex, comm):
            matches.append({"processId": pid, "processString": line})

    return jsonify(matches), 200

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)
